def base64_decode(string: str | bytes) -> bytes:
    """Base64 decode a URL-safe string of bytes or text. The result is
    bytes.
    """
    string = want_bytes(string, encoding="ascii", errors="ignore")
    string += b"=" * (-len(string) % 4)

    try:
        return base64.urlsafe_b64decode(string)
    except (TypeError, ValueError) as e:
        raise BadData("Invalid base64-encoded data") from e

def derive_key(self, secret_key: str | bytes | None = None) -> bytes:
    """This method is called to derive the key. The default key
    derivation choices can be overridden here. Key derivation is not
    intended to be used as a security method to make a complex key
    out of a short password. Instead you should use large random
    secret keys.

    :param secret_key: A specific secret key to derive from.
        Defaults to the last item in :attr:`secret_keys`.

    .. versionchanged:: 2.0
        Added the ``secret_key`` parameter.
    """
    if secret_key is None:
        secret_key = self.secret_keys[-1]
    else:
        secret_key = want_bytes(secret_key)

    if self.key_derivation == "concat":
        return t.cast(bytes, self.digest_method(self.salt + secret_key).digest())
    elif self.key_derivation == "django-concat":
        return t.cast(
            bytes, self.digest_method(self.salt + b"signer" + secret_key).digest()
        )
    elif self.key_derivation == "hmac":
        mac = hmac.new(secret_key, digestmod=self.digest_method)
        mac.update(self.salt)
        return mac.digest()
    elif self.key_derivation == "none":
        return secret_key
    else:
        raise TypeError("Unknown key derivation method")

def iter_unsigners(self, salt: str | bytes | None = None) -> cabc.Iterator[Signer]:
    """Iterates over all signers to be tried for unsigning. Starts
    with the configured signer, then constructs each signer
    specified in ``fallback_signers``.
    """
    if salt is None:
        salt = self.salt

    yield self.make_signer(salt)

    for fallback in self.fallback_signers:
        if isinstance(fallback, dict):
            kwargs = fallback
            fallback = self.signer
        elif isinstance(fallback, tuple):
            fallback, kwargs = fallback
        else:
            kwargs = self.signer_kwargs

        for secret_key in self.secret_keys:
            yield fallback(secret_key, salt=salt, **kwargs)

def verify_signature(self, value: str | bytes, sig: str | bytes) -> bool:
    """Verifies the signature for the given value."""
    try:
        sig = base64_decode(sig)
    except Exception:
        return False

    value = want_bytes(value)

    for secret_key in reversed(self.secret_keys):
        key = self.derive_key(secret_key)

        if self.algorithm.verify_signature(key, value, sig):
            return True

    return False

def _loads_unsafe_impl(
    self,
    s: str | bytes,
    salt: str | bytes | None,
    load_kwargs: dict[str, t.Any] | None = None,
    load_payload_kwargs: dict[str, t.Any] | None = None,
) -> tuple[bool, t.Any]:
    """Low level helper function to implement :meth:`loads_unsafe`
    in serializer subclasses.
    """
    if load_kwargs is None:
        load_kwargs = {}

    try:
        return True, self.loads(s, salt=salt, **load_kwargs)
    except BadSignature as e:
        if e.payload is None:
            return False, None

        if load_payload_kwargs is None:
            load_payload_kwargs = {}

        try:
            return (
                False,
                self.load_payload(e.payload, **load_payload_kwargs),
            )
        except BadPayload:
            return False, None

def load_payload(
    self,
    payload: bytes,
    *args: t.Any,
    serializer: t.Any | None = None,
    **kwargs: t.Any,
) -> t.Any:
    decompress = False

    if payload.startswith(b"."):
        payload = payload[1:]
        decompress = True

    try:
        json = base64_decode(payload)
    except Exception as e:
        raise BadPayload(
            "Could not base64 decode the payload because of an exception",
            original_error=e,
        ) from e

    if decompress:
        try:
            json = zlib.decompress(json)
        except Exception as e:
            raise BadPayload(
                "Could not zlib decompress the payload before decoding the payload",
                original_error=e,
            ) from e

    return super().load_payload(json, *args, **kwargs)

def unsign(self, signed_value: str | bytes) -> bytes:
    """Unsigns the given string."""
    signed_value = want_bytes(signed_value)

    if self.sep not in signed_value:
        raise BadSignature(f"No {self.sep!r} found in value")

    value, sig = signed_value.rsplit(self.sep, 1)

    if self.verify_signature(value, sig):
        return value

    raise BadSignature(f"Signature {sig!r} does not match", payload=value)

def dump_payload(self, obj: t.Any) -> bytes:
    """Dumps the encoded object. The return value is always bytes.
    If the internal serializer returns text, the value will be
    encoded as UTF-8.
    """
    return want_bytes(self.serializer.dumps(obj, **self.serializer_kwargs))

def make_signer(self, salt: str | bytes | None = None) -> Signer:
    """Creates a new instance of the signer to be used. The default
    implementation uses the :class:`.Signer` base class.
    """
    if salt is None:
        salt = self.salt

    return self.signer(self.secret_keys, salt=salt, **self.signer_kwargs)

def sign(self, value: str | bytes) -> bytes:
    """Signs the given string."""
    value = want_bytes(value)
    return value + self.sep + self.get_signature(value)

def get_timestamp(self) -> int:
    """Returns the current timestamp. The function must return an
    integer.
    """
    return int(time.time())

def base64_encode(string: str | bytes) -> bytes:
    """Base64 encode a string of bytes or text. The resulting bytes are
    safe to use in URLs.
    """
    string = want_bytes(string)
    return base64.urlsafe_b64encode(string).rstrip(b"=")

def verify_signature(self, key: bytes, value: bytes, sig: bytes) -> bool:
    """Verifies the given signature matches the expected
    signature.
    """
    return hmac.compare_digest(sig, self.get_signature(key, value))

def iter_unsigners(
    self, salt: str | bytes | None = None
) -> cabc.Iterator[TimestampSigner]:
    return t.cast("cabc.Iterator[TimestampSigner]", super().iter_unsigners(salt))

def change_set(previous: GraphGeneration, current: GraphInput) -> dict[str, list[str]]:
    old = {item.path: item.sha256 for item in previous.files}
    new = {item.path: item.sha256 for item in current.files}
    return {'added': sorted(set(new) - set(old)), 'deleted': sorted(set(old) - set(new)),
            'modified': sorted(path for path in set(old) & set(new) if old[path] != new[path])}

def parse_python(path: str, content: bytes, config: GraphConfig) -> ParsedFile:
    digest = hashlib.sha256(content).hexdigest()
    if len(content) > config.max_file_bytes:
        return ParsedFile(path, digest, 'python', 'incomplete', 'FILE_OVER_GRAPH_LIMIT')
    try:
        text = _decode(content)
    except (SyntaxError, LookupError, UnicodeDecodeError):
        return ParsedFile(path, digest, 'python', 'incomplete', 'ENCODING_ERROR')
    try:
        with warnings.catch_warnings():
            warnings.simplefilter('ignore')
            tree = ast.parse(text, filename=path, type_comments=False)
    except (SyntaxError, ValueError, RecursionError, MemoryError):
        return ParsedFile(path, digest, 'python', 'incomplete', 'SYNTAX_ERROR')
    visitor = _Visitor(path)
    try:
        for statement in tree.body:
            visitor.visit(statement)
    except RecursionError:
        return ParsedFile(path, digest, 'python', 'incomplete', 'NESTING_TOO_DEEP')
    return ParsedFile(path, digest, 'python', 'complete', None, tuple(visitor.symbols), tuple(visitor.imports),
                      tuple(visitor.calls), {name: tuple(kinds) for name, kinds in visitor.module_bindings.items()},
                      {scope: frozenset(names) for scope, names in visitor.locals.items()},
                      tuple(sorted(visitor.patched)), tuple(visitor.gaps))

def route_ingestion(input_spec: Mapping[str, Any], policy: IngestPolicy) -> IngestionRoute:
    """input_spec: {'path', optional 'kind' (folder/local_git/remote_snapshot), optional 'origin'}."""
    root = Path(input_spec['path'])
    declared = input_spec.get('kind')
    if declared is not None and declared not in SOURCE_KINDS:
        return IngestionRoute('blocked', None, str(root), ('UNKNOWN_INPUT_KIND',))
    if not root.is_dir() or root.is_symlink():
        return IngestionRoute('blocked', declared, str(root), ('INPUT_NOT_A_DIRECTORY',))
    marker = git_marker(root)
    if marker == 'link':
        return IngestionRoute('blocked', declared, str(root), ('GIT_MARKER_IS_A_LINK',))
    parent = None if marker else enclosing_worktree(root)
    detected = 'git' if marker else ('inside_repository' if parent else 'folder')
    if detected == 'inside_repository':
        return IngestionRoute('blocked', declared, str(root), ('INSIDE_PARENT_GIT_WORKTREE',),
                              next_command=f'inspect the enclosing repository {parent} instead')
    if declared == 'folder' and detected == 'git':
        return IngestionRoute('blocked', declared, str(root), ('AMBIGUOUS_INPUT_DECLARED_FOLDER_HAS_GIT',))
    if declared in ('local_git', 'remote_snapshot') and detected == 'folder':
        return IngestionRoute('blocked', declared, str(root), ('AMBIGUOUS_INPUT_DECLARED_GIT_HAS_NO_GIT',))
    if declared == 'remote_snapshot' and not input_spec.get('origin'):
        return IngestionRoute('blocked', declared, str(root), ('REMOTE_SNAPSHOT_WITHOUT_ORIGIN',))
    identity = existing_workflow_identity(root)
    if detected == 'folder':
        return IngestionRoute('zero_git_plan', 'folder', str(root), (), None, identity,
                              'getzilla adopt plan --source <folder> --target <new folder>')
    kind = declared or 'local_git'
    try:
        baseline = inspect_git_input(root, policy, source_kind=kind, origin=input_spec.get('origin'))
    except IngestionError as error:
        return IngestionRoute('blocked', kind, str(root), (error.reason_code,), workflow_identity=identity)
    if baseline.state == 'unborn':
        return IngestionRoute('blocked', kind, str(root), (baseline.required_action,), baseline, identity)
    return IngestionRoute('existing_git_baseline', kind, str(root), baseline.provenance_limits, baseline, identity,
                          'getzilla install-into --plan <repository>')

def update_index(previous: GraphGeneration, current: GraphInput, store: GraphStore, *,
                 declared_changes: Iterable[str] | None = None) -> GraphGeneration:
    actual = change_set(previous, current)
    changed = {path for paths in actual.values() for path in paths}
    recorded = {item.path: item.sha256 for item in previous.files}
    reason = None
    if previous.graph_input.get('config') != current.config.to_dict():
        reason = 'CONFIG_OR_EXTRACTOR_CHANGED'
    elif previous.graph_input.get('source', {}).get('object_format') != current.source.object_format:
        reason = 'OBJECT_FORMAT_CHANGED'
    elif declared_changes is not None and set(declared_changes) != changed:
        reason = 'CHANGE_SET_INCONSISTENT'
    elif any(item.sha256 != recorded.get(path) for path, item in previous.parsed.items()):
        reason = 'CACHE_INCONSISTENT'
    expected = store.active_id()
    if reason is not None:
        generation = build_generation(current)
    else:
        reuse = {(path, item.sha256): item for path, item in previous.parsed.items() if path not in changed}
        generation = build_generation(current, reuse)
    generation = replace(generation, counters={**generation.counters, 'full_rebuild': int(reason is not None),
                                               'full_rebuild_reason': reason})
    store.publish(generation, expected_active=expected)
    return generation

def calculate_impact(previous: GraphGeneration | None, current: GraphGeneration,
                     changed_nodes: Iterable[str] | None = None, *, config: GraphConfig | None = None) -> ImpactReport:
    config = config or current.config
    generations = [current] if previous is None else [previous, current]
    if changed_nodes is None:
        if previous is None:
            changed = sorted(f'file:{item.path}' for item in current.files)
        else:
            delta = change_set(previous, current)
            changed = sorted(f'file:{path}' for paths in delta.values() for path in paths)
    else:
        changed = sorted({node if node.startswith(('file:', 'sym:')) else f'file:{node}' for node in changed_nodes})
    known = {f'file:{f.path}' for g in generations for f in g.files} | {s.id for g in generations for s in g.symbols}
    graph_nodes = {f'file:{f.path}' for g in generations for f in g.files if f.language == 'python'} | \
                  {s.id for g in generations for s in g.symbols}
    reasons: dict[str, set[str]] = {}
    gaps: list[str] = []
    for node in changed:
        reasons.setdefault(node, set()).add('CHANGED')
        if node not in known:
            gaps.append(f'CHANGED_NODE_NOT_IN_GRAPH:{node}')
        elif node not in graph_nodes:
            gaps.append(f'CHANGED_FILE_NOT_ANALYSED:{node}')
    reverse = _reverse_edges(generations)
    queue = deque(changed)
    seen = set(changed)
    limit_hit = False

    def visit(start: Iterable[str], why: str) -> None:
        nonlocal limit_hit
        for node in start:
            if node not in seen:
                seen.add(node)
                reasons.setdefault(node, set()).add(why)
                queue.append(node)
        while queue:
            node = queue.popleft()
            for dependent in sorted(reverse.get(node, ())):
                if dependent in seen:
                    reasons.setdefault(dependent, set()).add(f'DEPENDS_ON:{node}')
                    continue
                if len(seen) >= config.max_impact_nodes:
                    limit_hit = True
                    queue.clear()
                    return
                seen.add(dependent)
                reasons.setdefault(dependent, set()).add(f'DEPENDS_ON:{node}')
                queue.append(dependent)

    visit((), 'CHANGED')
    if changed:
        while not limit_hit:  # widen until no new gap file joins
            names = {node.rsplit('::', 1)[-1].rsplit('.', 1)[-1] for node in seen if node.startswith('sym:')}
            added = False
            for generation in generations:
                for node, why in sorted(_gap_files(generation, names).items()):
                    if node not in seen:
                        visit([node], why)
                        added = True
                    else:
                        reasons[node].add(why)
            if not added:
                break
    for generation in generations:
        coverage = generation.coverage
        gaps.extend(f'INCOMPLETE_PARSE:{path}:{why}' for path, why in coverage.incomplete)
        gaps.extend(f'UNSUPPORTED_LANGUAGE:{path}:{language}' for path, language in coverage.unsupported_language)
        gaps.extend(f'OMITTED:{path}:{why}' for path, why in coverage.omitted)
    if limit_hit:
        gaps.append('TRAVERSAL_LIMIT_REACHED')
    gaps = sorted(set(gaps))
    complete = not gaps
    fallback = 'none' if complete else 'configured_project'
    if not changed:
        gaps_note = ('NO_CHANGE_DETECTED',)
    else:
        gaps_note = ()
    required = (*ALWAYS_REQUIRED, 'affected_tests' if complete else 'full_test_suite', 'review')
    affected_files = tuple(sorted(node[5:] for node in seen if node.startswith('file:')))
    affected_symbols = tuple(sorted(node for node in seen if node.startswith('sym:')))
    return ImpactReport(None if previous is None else previous.generation_id, current.generation_id, tuple(changed),
                        affected_files, affected_symbols,
                        {node: tuple(sorted(why)) for node, why in reasons.items()}, complete,
                        tuple(gaps) + gaps_note, fallback, required, current.graph_input.get('source', {}))

def _reverse_edges(generations: Iterable[GraphGeneration]) -> dict[str, set[str]]:
    reverse: dict[str, set[str]] = {}
    for generation in generations:
        for edge in generation.imports:
            if edge.target_file is not None:
                reverse.setdefault(f'file:{edge.target_file}', set()).add(f'file:{edge.source_file}')
        for edge in generation.calls:
            if edge.resolution in ('exact', 'candidate'):
                caller_file = 'file:' + edge.caller.split(':', 1)[1].split('::', 1)[0]
                for target in edge.targets:
                    reverse.setdefault(target, set()).update({edge.caller, caller_file})
        for symbol in generation.symbols:
            reverse.setdefault(symbol.id, set()).add(f'file:{symbol.path}')
            reverse.setdefault(f'file:{symbol.path}', set()).add(symbol.id)
    return reverse

def visit_Call(self, node: ast.Call) -> None:
    chain = _chain(node.func)
    if chain is None:
        form, expression = 'dynamic', '<expression>'
        if isinstance(node.func, ast.Call) and _chain(node.func.func) in REFLECTION:
            form, expression = 'reflection', f'{_chain(node.func.func)}(...)'
    elif chain in DYNAMIC_IMPORT:
        form, expression = 'reflection', chain
        self.gaps.append(('DYNAMIC_IMPORT', node.lineno))
    elif chain in REFLECTION:
        form, expression = 'reflection', chain
        self.gaps.append(('REFLECTION', node.lineno))
    else:
        form, expression = ('name' if '.' not in chain else 'attribute'), chain
    self.calls.append(RawCall(self.qual, form, expression, node.lineno))
    self.generic_visit(node)

def read_active(self) -> GraphGeneration | None:
    active = self.active_id()
    return None if active is None else self.read_generation(active)

def read_generation(self, generation_id: str) -> GraphGeneration:
    row = self.db.execute('SELECT body, parsed, complete FROM generations WHERE id = ?', (generation_id,)).fetchone()
    if row is None or not row[2]:
        raise GraphError('GENERATION_NOT_FOUND', generation_id)
    generation = generation_from_record(json.loads(row[0]), json.loads(row[1]))
    if generation.generation_id != generation_id:
        raise GraphError('GENERATION_DIGEST_MISMATCH', generation_id)
    return generation

def _symbol(self, node: ast.AST, kind: str) -> None:
    name = node.name  # type: ignore[attr-defined]
    self._bind(name, 'class' if kind == 'class' else 'def')
    qualname = '.'.join([*self.scope, name])
    span = Span(node.lineno, node.col_offset, node.end_lineno or node.lineno, node.end_col_offset or 0)
    self.symbols.append(SymbolNode(self.path, qualname, kind, span))
    for decorator in getattr(node, 'decorator_list', []):
        self.visit(decorator)
    for default in getattr(getattr(node, 'args', None), 'defaults', []) or []:
        self.visit(default)
    for base in getattr(node, 'bases', []):
        self.visit(base)
    self.scope.append(name)
    self.locals.setdefault(self.qual, set())
    args = getattr(node, 'args', None)
    if args is not None:
        for arg in [*args.posonlyargs, *args.args, *args.kwonlyargs, args.vararg, args.kwarg]:
            if arg is not None:
                self.locals[self.qual].add(arg.arg)
    for statement in node.body:  # type: ignore[attr-defined]
        self.visit(statement)
    self.scope.pop()

def _gap_files(generation: GraphGeneration, names: set[str]) -> dict[str, str]:
    """Files whose unresolved calls could reach a symbol named in `names` (or anything, for reflection)."""
    gaps: dict[str, str] = {}
    for edge in generation.calls:
        if edge.resolution != 'unresolved':
            continue
        if edge.reason in ANY_TARGET or edge.expression.rsplit('.', 1)[-1] in names:
            path = edge.caller.split(':', 1)[1].split('::', 1)[0]
            gaps.setdefault(f'file:{path}', f'UNRESOLVED_CALL_MAY_REACH_CHANGE:{edge.reason}')
    for edge in generation.imports:
        if edge.resolution == 'unresolved':
            gaps.setdefault(f'file:{edge.source_file}', f'UNRESOLVED_IMPORT:{edge.reason}')
    for path, parsed in generation.parsed.items():
        if parsed.dynamic_gaps:
            gaps.setdefault(f'file:{path}', f'DYNAMIC_GAP:{parsed.dynamic_gaps[0][0]}')
    return gaps
